<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Collective;use Illuminate\Http\Request;use Illuminate\Support\Str;class CollectiveController extends Controller{public function index(){return view('admin.collectives.index',['items'=>Collective::orderBy('sort')->get()]);}public function create(){return view('admin.collectives.form',['item'=>new Collective]);}public function store(Request $r){Collective::create($this->data($r));return redirect()->route('admin.collectives.index')->with('ok','Коллектив добавлен');}public function edit(Collective $collective){return view('admin.collectives.form',['item'=>$collective]);}public function update(Request $r,Collective $collective){$collective->update($this->data($r));return redirect()->route('admin.collectives.index')->with('ok','Сохранено');}public function destroy(Collective $collective){$collective->delete();return back();}private function data(Request $r){$d=$r->validate(['name'=>'required|max:255','leader'=>'nullable|max:255','description'=>'nullable','sort'=>'nullable|integer','image'=>'nullable|image|max:10240']);$d['slug']=Str::slug($r->input('slug')?:$d['name']);if($r->hasFile('image'))$d['image']=$r->file('image')->store('collectives','public');$d['is_active']=$r->boolean('is_active');return $d;}}